{
 "opening": "This release introduces significant enhancements to the humanization capabilities of Arrow, including new granularity options and expanded locale support. It also ensures stricter validation for input parameters to improve robustness.",
 "requirements": [
  {
   "id": "m01",
   "text": "The HebrewLocale must correctly handle plural forms for years and days in localized time strings."
  },
  {
   "id": "m02",
   "text": "The library must provide a fully functional SinhalaLocale for date and time localization. The describe function should be available to support these locale-specific descriptions."
  },
  {
   "id": "m04",
   "text": "The library must include a fully translated UrduLocale for accurate date and time localization. The SinhalaLocale must remain functional alongside the new Urdu support."
  },
  {
   "id": "m10",
   "text": "The AzerbaijaniLocale must correctly format second and week time frames according to updated local conventions. The translation for 'a year' must be consistent with standard Azerbaijani usage."
  },
  {
   "id": "m11",
   "text": "The humanize method must accept a granularity parameter set to 'quarter' to return results like 'a quarter ago' or 'in 4 quarters'. This behavior must apply consistently across EnglishLocale and the base Locale implementation."
  },
  {
   "id": "m12",
   "text": "Passing an empty list as the granularity argument to the humanize method must raise a ValueError. The error message provided must be descriptive and clear to the user."
  }
 ],
 "closing": "Please ensure all new locales are properly integrated and that the existing functionality remains stable under these changes."
}
